require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);if(session_status()===PHP_SESSION_ACTIVE)session_write_close();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT image_path,image_mime FROM family_recipes WHERE id=?');$q->execute([$id]);$r=$q->fetch();if(!$r||!$r['image_path']||!str_starts_with($r['image_path'],'storage/recipes/')){http_response_code(404);exit;}$file=__DIR__.'/'.$r['image_path'];if(!is_file($file)){http_response_code(404);exit;}$mime=(string)($r['image_mime']?:'image/jpeg');if(str_ends_with(strtolower($file),'.jpg'))$mime='image/jpeg';header('Content-Type: '.$mime);header('Cache-Control: private, max-age=604800');header('Content-Length: '.filesize($file));readfile($file);
